export const ONLINE_SCAMS_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu penipuan online & phishing
{n:1,type:"mcq",micro:"Apa itu penipuan online",q:"'Penipuan online' (scam) adalah...",options:["Usaha menipu seseorang lewat internet untuk mendapatkan uang, data, atau keuntungan lain secara tidak sah","Iklan yang menawarkan diskon besar dari toko resmi","Permainan daring yang butuh strategi"],answer:0,explain:"Penipuan online memakai tipu daya untuk membuat korban memberikan sesuatu yang berharga, uang, data, atau akses.",hint:"Usaha menipu lewat internet, atau diskon resmi?"},
{n:2,type:"mcq",micro:"Apa itu phishing",q:"'Phishing' (pengelabuan) adalah...",options:["Permainan mencari ikan virtual","Usaha menipu seseorang agar memberikan info pribadi (kata sandi, data kartu) dengan berpura-pura jadi pihak tepercaya","Cara resmi bank mengirim info akun"],answer:1,explain:"Nama 'phishing' berasal dari 'fishing' (memancing), penipu 'memancing' korban dengan umpan yang terlihat sah.",hint:"Menipu agar memberi info pribadi, atau cara resmi bank?"},
{n:3,type:"mcq",micro:"Ciri umum penipuan",q:"Pola yang sering muncul di penipuan online:",options:["Penjelasan yang jelas & tidak terburu-buru","Tidak pernah meminta apa pun dari korban","Janji terlalu bagus (hadiah besar, untung cepat), mendesak segera bertindak, & meminta info/uang di muka"],answer:2,explain:"Kombinasi 'terlalu bagus' + 'mendesak' + 'minta sesuatu di muka' adalah tanda klasik yang perlu diwaspadai.",hint:"Janji besar + mendesak + minta sesuatu, atau jelas & santai?"},
{n:4,type:"mcq",micro:"Penipuan hadiah palsu",q:"Pesan 'Selamat! Kamu memenangkan HP terbaru, klik link ini & isi data untuk klaim' padahal kamu tidak pernah ikut undian apa pun...",options:["Sangat mencurigakan; kamu tidak bisa menang undian yang tidak pernah kamu ikuti","Selalu benar karena disebut 'selamat'","Pasti aman kalau linknya terlihat resmi"],answer:0,explain:"Kalau tidak pernah mendaftar undian, mustahil menang. Ini pola umum penipuan hadiah palsu.",hint:"Tidak mungkin menang undian yang tak diikuti, atau selalu benar?"},
{n:5,type:"mcq",micro:"Link mencurigakan",q:"Sebelum mengklik sebuah tautan (link) yang dikirim orang tak dikenal, kebiasaan yang aman:",options:["Kirimkan ke semua teman dulu sebelum diperiksa","Periksa dulu ke mana arah link itu (arahkan kursor tanpa klik, atau lihat pratinjau) & pertimbangkan apakah masuk akal","Klik saja untuk melihat apa isinya"],answer:1,explain:"Memeriksa tujuan link sebelum mengklik bisa mencegah membuka situs berbahaya atau memicu unduhan berbahaya.",hint:"Periksa dulu tujuannya, atau klik saja / sebar dulu?"},
{n:6,type:"mcq",micro:"Meminta info sensitif",q:"Pesan yang meminta kamu mengirim nomor kartu, kata sandi, atau kode OTP lewat chat/email adalah...",options:["Wajar & harus dituruti kalau yang meminta terlihat resmi","Hanya berbahaya kalau dikirim lewat SMS, aman lewat email","Tanda bahaya besar; institusi resmi tidak pernah meminta info sensitif seperti itu lewat pesan"],answer:2,explain:"Bank, toko, & layanan resmi tidak akan meminta kata sandi atau kode OTP lewat pesan. Ini pola phishing yang sangat umum.",hint:"Tanda bahaya besar, atau wajar dituruti / hanya berbahaya lewat SMS?"},
{n:7,type:"mcq",micro:"Mendesak bertindak cepat",q:"Kenapa penipu sering membuat pesannya terasa 'sangat mendesak' (harus bertindak dalam 10 menit)?",options:["Agar korban tidak sempat berpikir jernih atau memeriksa kebenarannya","Karena mereka memang sangat sibuk","Karena aturan resmi memang selalu seperti itu"],answer:0,explain:"Tekanan waktu adalah taktik untuk melewati logika & membuat orang bertindak dari rasa panik, bukan pertimbangan.",hint:"Agar tak sempat berpikir, atau karena sibuk / aturan resmi?"},
{n:8,type:"mcq",micro:"Meniru otoritas",q:"Pesan yang berpura-pura dari 'bank', 'polisi', atau 'sekolah' untuk membuat korban patuh tanpa curiga adalah taktik...",options:["Tidak pernah dipakai penipu","Meniru otoritas agar korban merasa harus menurut karena takut atau menghormati","Cara resmi lembaga tersebut selalu berkomunikasi"],answer:1,explain:"Meniru nama lembaga tepercaya membuat orang cenderung tidak curiga & langsung menurut.",hint:"Meniru otoritas, atau cara resmi lembaga?"},
{n:9,type:"order",micro:"Menghadapi pesan mencurigakan",q:"Urutkan langkah aman saat menerima pesan yang mencurigakan.",items:["Jangan klik link atau membalas dengan info pribadi dulu","Perhatikan tanda bahaya (mendesak, janji besar, meminta info sensitif)","Verifikasi lewat kanal resmi terpisah (bukan lewat pesan itu sendiri)","Blokir/laporkan bila terbukti penipuan, & beri tahu orang dewasa bila perlu"],answer:[0,1,2,3],explain:"Jangan bertindak dulu → kenali tanda → verifikasi mandiri → blokir & laporkan. Jangan pernah membalas lewat kanal yang sama dengan pesan mencurigakan.",hint:"Memverifikasi lewat kanal resmi dilakukan sebelum atau sesudah mengenali tanda bahaya?"},
{n:10,type:"mcq",micro:"Terlalu bagus untuk jadi benar",q:"Tawaran 'investasi untung 50% per minggu tanpa risiko' adalah contoh klasik...",options:["Peluang emas yang harus segera diambil","Investasi resmi yang aman","Penipuan; keuntungan sebesar & sepasti itu tanpa risiko tidak realistis dalam investasi apa pun"],answer:2,explain:"Semua investasi sah punya risiko. Janji untung besar & pasti tanpa risiko adalah tanda penipuan investasi (skema Ponzi & sejenisnya).",hint:"Tanda penipuan investasi, atau peluang emas?"},
{n:11,type:"tf",micro:"Penipuan hanya menyasar orang tua",q:"Benar atau Salah: Penipuan online hanya menyasar orang dewasa/lansia, anak-anak & remaja tidak pernah jadi target.",answer:false,explain:"Sebaliknya, anak & remaja juga jadi target, terutama lewat penipuan game, giveaway palsu, & tawaran 'akun gratis'.",hint:"Hanya menyasar dewasa/lansia, atau semua usia bisa jadi target?"},
{n:12,type:"tf",micro:"Alamat pengirim bisa dipalsukan",q:"Benar atau Salah: Nama & alamat pengirim pesan/email bisa dipalsukan agar terlihat seperti dari sumber resmi, meski sebenarnya bukan.",answer:true,explain:"Teknik 'spoofing' membuat pesan terlihat datang dari nomor/alamat resmi padahal aslinya dari penipu. Tampilan saja tidak cukup dipercaya.",hint:"Bisa dipalsukan, atau selalu asli sesuai tampilan?"},
{n:13,type:"mcq",micro:"Kode OTP",q:"'OTP' (kode sekali pakai) yang dikirim lewat SMS/aplikasi berfungsi untuk...",options:["Memverifikasi bahwa benar-benar kamu yang mencoba login/transaksi; membagikannya ke orang lain berarti memberi mereka akses","Hiburan semata tanpa fungsi keamanan","Boleh dibagikan ke siapa saja yang memintanya dengan sopan"],answer:0,explain:"OTP adalah kunci sekali pakai. Siapa pun yang memintanya (meski mengaku dari layanan resmi) kemungkinan besar penipu.",hint:"Verifikasi identitas & jangan dibagikan, atau boleh dibagikan?"},
{n:14,type:"mcq",micro:"Penipuan jual-beli online",q:"Penjual daring meminta pembayaran penuh di muka lewat transfer pribadi (bukan lewat sistem resmi toko/rekening bersama), tanpa jaminan apa pun. Ini...",options:["Wajar untuk semua transaksi daring","Berisiko; tanpa sistem rekening bersama/perlindungan pembeli, uang bisa hilang tanpa barang dikirim","Selalu aman selama penjualnya ramah"],answer:1,explain:"Sistem pembayaran resmi (rekening bersama/escrow, metode resmi platform) memberi perlindungan yang tidak ada pada transfer langsung tanpa jaminan.",hint:"Berisiko tanpa perlindungan resmi, atau selalu aman?"},
{n:15,type:"mcq",micro:"Penipuan item/akun game",q:"Tawaran 'item game gratis, tinggal login pakai akunmu di situs ini' dari orang tak dikenal biasanya...",options:["Selalu aman & sah dari pengembang game","Cara resmi menukar item","Cara mencuri akun game (phishing), bukan hadiah asli"],answer:2,explain:"Situs 'pihak ketiga' yang minta login akun game sering dipakai mencuri akun & isinya, bukan memberi hadiah sungguhan.",hint:"Cara mencuri akun, atau selalu aman?"},
{n:16,type:"tf",micro:"Penipu bisa berpura-pura jadi teman",q:"Benar atau Salah: Akun seseorang tidak mungkin dipakai penipu untuk berpura-pura jadi teman kita, karena penipu selalu memakai akun sendiri.",answer:false,explain:"Sebaliknya, akun teman yang diretas bisa dipakai penipu untuk mengirim pesan seolah dari temanmu, meminta uang atau info dengan alasan mendesak. Verifikasi lewat cara lain (telepon langsung) penting.",hint:"Bisa dipakai berpura-pura jadi teman, atau tidak mungkin terjadi?"},
{n:17,type:"mcq",micro:"Penipuan berbasis rasa takut",q:"Pesan 'Akunmu akan diblokir permanen dalam 1 jam kecuali kamu verifikasi sekarang' memakai emosi...",options:["Rasa takut kehilangan sesuatu, untuk mendorong tindakan cepat tanpa berpikir","Rasa bosan","Tidak memakai emosi apa pun"],answer:0,explain:"Ketakutan kehilangan akses (akun, uang, kesempatan) adalah pemicu emosi yang sering dipakai penipu untuk mendesak korban.",hint:"Rasa takut kehilangan, atau bosan?"},
{n:18,type:"mcq",micro:"Penipuan berbasis keserakahan",q:"Sebaliknya, tawaran 'uang gratis/hadiah besar tanpa usaha' memakai emosi...",options:["Rasa marah","Harapan mendapat sesuatu secara mudah, yang membuat orang mengabaikan tanda bahaya","Rasa takut"],answer:1,explain:"Godaan mendapat sesuatu besar dengan mudah bisa membuat kewaspadaan menurun. Keduanya (takut & tergiur) sering dipakai bergantian.",hint:"Harapan mendapat mudah, atau rasa takut/marah?"},
{n:19,type:"mcq",micro:"Aplikasi/situs tak resmi yang menjanjikan sesuatu",q:"Situs yang menjanjikan 'generator koin/item gratis tak terbatas' untuk sebuah game biasanya...",options:["Cara sah yang disetujui pengembang game","Selalu berhasil tanpa risiko","Penipuan atau usaha mencuri akun/data, karena tidak ada cara sah menghasilkan item tak terbatas gratis"],answer:2,explain:"'Generator' semacam ini hampir selalu tipuan untuk mencuri akun atau menipu lewat survei/unduhan berbahaya.",hint:"Penipuan/pencurian akun, atau cara sah?"},
{n:20,type:"open",micro:"Analisis sebuah pesan penipuan",q:"Bayangkan kamu menerima pesan WhatsApp: 'Ini Kak Rani, HP-ku hilang, aku pakai nomor baru. Tolong transferin uang buat beli tiket pulang, nanti aku ganti pas sudah sampai rumah, mendesak banget ini.' Analisis: (a) minimal 3 tanda kecurigaan, (b) langkah yang akan kamu lakukan sebelum bertindak, (c) bagaimana kamu akan menjelaskan kejadian ini ke Kak Rani yang asli setelahnya (untuk membantu dia tahu ada yang meniru identitasnya).",sample:"(a) Tanda kecurigaan: (1) Nomor baru yang tidak dikenal mengaku sebagai orang yang biasanya dikenal lewat nomor lain, klasik modus mengganti identitas. (2) Meminta uang dengan alasan mendesak ('mendesak banget'), memicu rasa panik agar tidak sempat berpikir. (3) Janji 'nanti aku ganti' tanpa bukti apa pun, sangat umum dipakai penipu untuk membuat korban merasa ini pinjaman wajar, bukan penipuan. (b) Langkah sebelum bertindak: aku tidak akan langsung transfer; aku akan mencoba menghubungi Kak Rani lewat nomor lamanya yang kukenal (telepon langsung, bukan chat), atau menelepon keluarganya/orang lain yang mengenalnya untuk memastikan apakah dia benar-benar kehilangan HP; kalau tidak bisa dihubungi lewat cara lain, aku akan menganggapnya mencurigakan & tidak mengirim apa pun sampai benar-benar terkonfirmasi. (c) Menjelaskan ke Kak Rani asli: aku akan bilang, 'Kak, ada nomor yang ngaku Kakak, bilang HP-nya hilang & minta ditransferin uang buat tiket, aku curiga itu penipuan, mau kasih tahu aja siapa tahu ada yang lain juga dikirimin pesan serupa. Mungkin bisa diinfoin ke grup keluarga/teman biar semua waspada.'",explain:"Jawaban baik: 3 tanda kecurigaan yang spesifik (nomor baru mengaku identitas lama, urgensi, janji balas tanpa bukti), langkah verifikasi yang benar (hubungi lewat kanal lain yang sudah dikenal, bukan membalas di kanal yang sama), & rencana memberi tahu orang yang identitasnya ditiru supaya bisa memperingatkan orang lain juga.",hint:"Kunci verifikasi: selalu hubungi lewat kanal LAIN yang sudah kamu kenal sebelumnya, jangan percaya nomor baru begitu saja."},

// FASE B — PEMAHAMAN (21-40): teknik penipu, rekayasa sosial
{n:21,type:"classify",micro:"Tanda penipuan vs komunikasi wajar",q:"Kelompokkan tiap pesan ke 'Tanda penipuan' atau 'Komunikasi wajar'.",items:["'Segera verifikasi akunmu dalam 10 menit atau hilang selamanya!'","'Terima kasih atas pesananmu, berikut nomor resi untuk dilacak.'","'Kirimkan kode OTP-mu untuk memvalidasi akun.'","'Ada pertanyaan? Hubungi kami lewat nomor resmi di aplikasi.'"],groups:["Tanda penipuan","Komunikasi wajar"],answer:{"Tanda penipuan":["'Segera verifikasi akunmu dalam 10 menit atau hilang selamanya!'","'Kirimkan kode OTP-mu untuk memvalidasi akun.'"],"Komunikasi wajar":["'Terima kasih atas pesananmu, berikut nomor resi untuk dilacak.'","'Ada pertanyaan? Hubungi kami lewat nomor resmi di aplikasi.'"]},explain:"Tanda penipuan: mendesak & minta OTP. Wajar: informasi transaksi & mengarahkan ke kanal resmi tanpa meminta data sensitif.",hint:"Mendesak & minta OTP, atau informasi biasa & arahkan ke kanal resmi?"},
{n:22,type:"mcq",micro:"Rekayasa sosial",q:"'Rekayasa sosial' (social engineering) dalam penipuan berarti...",options:["Memanipulasi psikologi/perasaan seseorang (percaya, takut, tergiur) untuk membuat mereka bertindak sesuai keinginan penipu","Merancang aplikasi sosial media baru","Teknik memperbaiki jaringan sosial"],answer:0,explain:"Rekayasa sosial menyerang manusia, bukan sistem komputer. Ia memanfaatkan kepercayaan, ketakutan, & kebiasaan sosial.",hint:"Memanipulasi psikologi orang, atau merancang aplikasi?"},
{n:23,type:"mcq",micro:"Meniru situs resmi (URL mirip)",q:"Alamat 'shop-online-resmi.xyz' yang meniru toko besar tapi dengan domain aneh adalah taktik...",options:["Selalu jelas terlihat sebagai situs asli","Membuat situs palsu terlihat mirip yang asli untuk mengelabui, meski alamatnya sedikit berbeda","Cara resmi toko membuat cabang baru"],answer:1,explain:"Memeriksa alamat situs dengan teliti (domain resmi, ejaan, akhiran) membantu mengenali situs tiruan.",hint:"Meniru situs asli dengan alamat mirip, atau cara resmi buka cabang?"},
{n:24,type:"mcq",micro:"Skema piramida/Ponzi sederhana",q:"Skema yang menjanjikan untung besar dari 'merekrut orang lain untuk ikut' lebih dari dari produk/jasa nyata biasanya...",options:["Bisnis sah yang menguntungkan semua orang","Cara investasi paling aman","Skema piramida/Ponzi, tidak berkelanjutan & akhirnya merugikan sebagian besar pesertanya"],answer:2,explain:"Kalau keuntungan utama datang dari uang orang baru yang direkrut (bukan produk nyata), skema ini pasti runtuh & merugikan yang bergabung belakangan.",hint:"Skema tak berkelanjutan yang merugikan, atau bisnis sah?"},
{n:25,type:"mcq",micro:"Penipuan romantis sederhana (untuk konteks anak/remaja)",q:"Orang yang baru dikenal daring, cepat sekali menyatakan sayang/perhatian besar, lalu mulai meminta uang/hadiah/info pribadi adalah pola...",options:["Mencurigakan; kedekatan instan yang diikuti permintaan uang/info adalah taktik manipulasi umum","Tanda cinta sejati yang harus dipercaya penuh","Wajar terjadi pada semua pertemanan daring baru"],answer:0,explain:"Kedekatan emosional yang dibangun cepat lalu diikuti permintaan (uang, foto pribadi, info) adalah pola manipulasi yang perlu diwaspadai, apa pun konteksnya.",hint:"Pola manipulasi yang perlu diwaspadai, atau tanda cinta sejati?"},
{n:26,type:"mcq",micro:"Penipuan 'akun bermasalah'",q:"Pesan 'Akun media sosialmu terdeteksi melanggar aturan, klik untuk banding' dari akun/nomor yang tidak resmi adalah pola umum untuk...",options:["Selalu bisa dipercaya karena menyebut 'aturan'","Memancing korban mengklik link phishing yang mencuri kata sandi","Cara resmi platform memberi tahu masalah"],answer:1,explain:"Rasa panik takut kehilangan akun sering membuat orang buru-buru mengklik tanpa memeriksa keaslian pengirimnya.",hint:"Memancing klik phishing, atau cara resmi platform?"},
{n:27,type:"tf",micro:"Kesalahan ejaan sebagai petunjuk",q:"Benar atau Salah: Kesalahan ejaan, tata bahasa aneh, atau terjemahan kaku dalam pesan yang mengaku dari bank/perusahaan besar tidak relevan sama sekali untuk menilai keasliannya.",answer:false,explain:"Sebaliknya, meski bukan bukti mutlak, komunikasi resmi biasanya melewati pengecekan bahasa. Kesalahan mencolok patut menambah kecurigaan.",hint:"Bisa jadi petunjuk, atau tidak relevan sama sekali?"},
{n:28,type:"tf",micro:"Semua pesan hadiah pasti penipuan?",q:"Benar atau Salah: Semua pesan yang menyebut 'hadiah' atau 'promo' pasti penipuan tanpa terkecuali.",answer:false,explain:"Sebaliknya, tidak semua, ada promo & hadiah yang sah dari toko/acara resmi yang memang kamu ikuti. Yang perlu dicurigai adalah polanya (tidak pernah ikut, mendesak, minta info sensitif), bukan sekadar kata 'hadiah'.",hint:"Semua pasti penipuan, atau tergantung tanda & konteksnya?"},
{n:29,type:"mcq",micro:"Penipuan lewat panggilan suara",q:"Penipuan tidak hanya lewat teks; panggilan telepon yang mengaku dari 'bank/polisi' & meminta info rekening/OTP lewat suara juga...",options:["Selalu aman karena bisa mendengar suaranya","Hanya berbahaya kalau lewat teks, bukan suara","Sama berbahayanya; jangan berikan info sensitif lewat telepon dari nomor yang tidak bisa diverifikasi"],answer:2,explain:"Modus penipuan lewat telepon (vishing) sama nyatanya dengan lewat pesan. Suara yang meyakinkan bukan jaminan keaslian.",hint:"Sama berbahayanya, atau hanya lewat teks?"},
{n:30,type:"order",micro:"Mengenali pola rekayasa sosial",q:"Urutkan tahap umum sebuah penipuan rekayasa sosial.",items:["Penipu membangun kepercayaan/kedekatan atau berpura-pura jadi otoritas","Penipu menciptakan rasa mendesak atau emosi kuat (takut/tergiur)","Penipu meminta sesuatu (uang, info, akses) sebelum korban sempat berpikir","Penipu menghilang setelah mendapatkan yang diinginkan"],answer:[0,1,2,3],explain:"Bangun kepercayaan → ciptakan urgensi/emosi → minta sesuatu → menghilang. Mengenali pola ini di awal membantu berhenti sebelum tahap ketiga.",hint:"Menciptakan urgensi terjadi sebelum atau sesudah membangun kepercayaan?"},
{n:31,type:"mcq",micro:"Penipuan lewat lowongan/pekerjaan palsu",q:"Tawaran 'kerja mudah, gaji besar, cukup dari HP, hubungi nomor ini' yang meminta 'biaya pendaftaran' di muka adalah...",options:["Pola umum penipuan lowongan kerja; pekerjaan sah jarang meminta pembayaran dari pelamar","Cara wajar perusahaan menyaring pelamar serius","Selalu aman karena menyebut 'gaji besar'"],answer:0,explain:"Meminta uang dari pencari kerja (bukan sebaliknya) adalah tanda bahaya besar dalam lowongan kerja.",hint:"Pola penipuan lowongan, atau cara wajar menyaring pelamar?"},
{n:32,type:"tf",micro:"Penipu meniru banyak pihak",q:"Benar atau Salah: Penipu selalu memakai satu jenis kedok yang sama (misalnya selalu mengaku bank) & tidak pernah berpura-pura jadi pihak lain.",answer:false,explain:"Sebaliknya, penipu bisa berpura-pura jadi berbagai pihak berbeda, bank, teman, sekolah, bahkan lembaga pemerintah, tergantung siapa yang menurut mereka bisa meyakinkan korban.",hint:"Bisa meniru banyak pihak, atau selalu satu jenis kedok?"},
{n:33,type:"mcq",micro:"Penipuan berbasis rasa bersalah/kewajiban",q:"'Sebagai warga negara yang baik, kamu wajib membayar denda ini sekarang' adalah taktik yang memanfaatkan...",options:["Tidak memanfaatkan emosi apa pun","Rasa kewajiban/takut melanggar aturan untuk mendorong kepatuhan tanpa berpikir","Rasa senang"],answer:1,explain:"Memainkan rasa 'harus patuh pada aturan/otoritas' adalah taktik yang efektif membuat orang tidak mempertanyakan keabsahannya.",hint:"Rasa kewajiban/takut melanggar, atau rasa senang?"},
{n:34,type:"mcq",micro:"Penipuan lewat aplikasi kencan/pertemanan",q:"Seseorang di aplikasi pertemanan yang menolak video call/bertemu langsung, tapi terus meminta uang/hadiah dengan berbagai alasan, adalah...",options:["Wajar karena mungkin pemalu","Selalu aman selama ceritanya masuk akal","Tanda bahaya besar; keengganan diverifikasi langsung dikombinasikan permintaan uang adalah pola penipuan umum"],answer:2,explain:"Menolak verifikasi (video call, bertemu) sambil terus meminta sesuatu adalah kombinasi klasik penipuan hubungan daring.",hint:"Tanda bahaya, atau wajar karena pemalu?"},
{n:35,type:"mcq",micro:"Penipuan hadiah 'bayar dulu ongkos kirim'",q:"'Kamu menang hadiah gratis, tinggal bayar ongkos kirim Rp50.000' untuk barang yang katanya bernilai jutaan adalah pola umum karena...",options:["Penipu mendapat uang kecil dari banyak korban tanpa pernah mengirim barang apa pun","Ongkos kirim memang selalu perlu dibayar pemenang","Ini selalu sah karena jumlahnya kecil"],answer:0,explain:"Jumlah kecil membuat orang merasa 'rugi sedikit tidak apa-apa', tapi dikalikan banyak korban jadi keuntungan besar bagi penipu, tanpa barang pernah dikirim.",hint:"Mengumpulkan uang kecil dari banyak korban, atau memang wajib bayar ongkir?"},
{n:36,type:"mcq",micro:"QR code palsu",q:"Kode QR yang ditempel menutupi kode QR asli di tempat pembayaran/parkir bisa mengarahkan ke...",options:["Tidak pernah dipakai untuk menipu","Rekening/situs penipu, bukan tujuan pembayaran yang sebenarnya","Selalu ke tempat yang sama seperti QR asli"],answer:1,explain:"Menempelkan QR palsu di atas yang asli adalah modus nyata. Memeriksa nama penerima sebelum membayar itu penting.",hint:"Bisa mengarah ke penipu, atau selalu sama dengan QR asli?"},
{n:37,type:"tf",micro:"Waspada tetap perlu meski platform aman",q:"Benar atau Salah: Memakai platform besar & tepercaya menjamin kamu otomatis aman, penipu tidak mungkin muncul di dalamnya.",answer:false,explain:"Sebaliknya, penipu tetap bisa muncul di platform besar (pesan pribadi, komentar, akun palsu). Platform berusaha menyaring, tapi tidak sepenuhnya bisa mencegah semuanya, jadi kewaspadaan pribadi tetap perlu.",hint:"Tetap perlu waspada, atau otomatis aman di platform besar?"},
{n:38,type:"mcq",micro:"Penipuan 'kamu terpilih' eksklusif",q:"Pesan yang membuatmu merasa 'terpilih secara khusus' untuk sesuatu yang tidak biasa berguna bagi penipu karena...",options:["Membuat korban curiga lebih cepat","Tidak berpengaruh pada keputusan korban","Membuat korban merasa istimewa & kurang kritis, serta enggan 'melewatkan kesempatan langka'"],answer:2,explain:"Rasa 'terpilih' & 'langka' memicu keinginan untuk segera mengambil kesempatan tanpa memeriksa dulu.",hint:"Membuat kurang kritis & takut kehilangan kesempatan, atau membuat lebih curiga?"},
{n:39,type:"mcq",micro:"Penipuan yang menyasar rasa iba",q:"Cerita yang sangat menyedihkan (sakit parah, kecelakaan) dari orang tak dikenal yang langsung meminta transfer uang tanpa bukti apa pun...",options:["Bisa jadi taktik memanfaatkan rasa iba; verifikasi lewat lembaga amal resmi lebih aman daripada transfer langsung ke individu tak dikenal","Selalu harus dipercaya karena kisahnya menyedihkan","Tidak pernah dipakai sebagai modus penipuan"],answer:0,explain:"Rasa iba adalah emosi kuat yang bisa dimanfaatkan. Menyumbang lewat lembaga resmi & terverifikasi lebih aman.",hint:"Verifikasi lewat lembaga resmi, atau percaya langsung karena menyedihkan?"},
{n:40,type:"open",micro:"Bedah sebuah tawaran mencurigakan",q:"Sebuah akun di media sosial (baru dibuat, sedikit pengikut) mempromosikan 'giveaway HP terbaru, cukup follow, like, share, & DM data dirimu (nama, alamat, nomor HP) untuk verifikasi'. Analisis: (a) 3 tanda kecurigaan, (b) kenapa 'follow, like, share' bisa menguntungkan penipu meski hadiahnya tidak nyata, (c) apa yang seharusnya dilakukan sebelum memberi data pribadi ke giveaway mana pun.",sample:"(a) Tanda kecurigaan: (1) Akun baru dengan sedikit pengikut jarang punya sumber daya nyata untuk memberi hadiah HP terbaru yang mahal. (2) Meminta data pribadi lengkap (nama, alamat, nomor HP) lewat DM sebagai syarat 'verifikasi', padahal giveaway sah biasanya cukup menghubungi pemenang lewat komentar/DM tanpa perlu semua data itu di awal untuk SEMUA peserta. (3) Tidak ada informasi jelas siapa penyelenggara sebenarnya, kapan pengundian, atau bukti giveaway sebelumnya yang benar-benar diberikan. (b) Kenapa menguntungkan meski hadiah tidak nyata: follow, like, & share menambah jumlah pengikut & jangkauan akun tersebut secara gratis (bisa dipakai untuk menipu lebih banyak orang lagi atau dijual sebagai 'akun dengan banyak pengikut'), sementara DM data pribadi dari ratusan/ribuan orang bisa dikumpulkan & disalahgunakan atau dijual, semua tanpa pernah memberi satu pun hadiah asli. (c) Yang seharusnya dilakukan: cek keaslian akun (sudah berapa lama, giveaway sebelumnya benar dibagikan atau tidak, apakah terverifikasi/resmi dari merek yang disebut), jangan pernah mengirim data pribadi lengkap hanya untuk 'ikut serta' (baru berikan data secukupnya SETELAH benar-benar menang & terverifikasi lewat cara yang masuk akal), & tanyakan pada diri sendiri apakah masuk akal sebuah akun kecil bisa memberi hadiah semahal itu tanpa syarat pembelian apa pun.",explain:"Jawaban baik: 3 tanda kecurigaan yang spesifik & masuk akal (akun baru, permintaan data berlebihan, ketiadaan transparansi), penjelasan yang menunjukkan paham bahwa data & interaksi (follow/like/share) sendiri punya nilai bagi penipu, & langkah pencegahan konkret sebelum memberi data pribadi ke giveaway.",hint:"Bagian (b) penting untuk dipahami: penipuan tidak selalu langsung minta uang, kadang targetnya data & interaksi yang bisa 'dijual' atau disalahgunakan nanti."},

// FASE C — PENERAPAN (41-60): praktik menghindari & menanggapi
{n:41,type:"mcq",micro:"Memeriksa alamat pengirim email",q:"Cara memeriksa keaslian email 'dari bank': lihat alamat email pengirim secara lengkap (bukan hanya nama tampilan), karena...",options:["Alamat email tidak pernah bisa diperiksa","Nama tampilan bisa ditulis apa saja, tapi alamat email asli (setelah tanda @) sulit dipalsukan sepenuhnya & sering mengungkap ketidakcocokan","Nama tampilan selalu sama dengan alamat aslinya"],answer:1,explain:"'Bank ABC <bankabc@gmail-verifikasi.xyz>' menunjukkan nama tampilan resmi tapi alamat asli yang aneh & tidak resmi.",hint:"Periksa alamat lengkap setelah @, atau percaya nama tampilan saja?"},
{n:42,type:"mcq",micro:"Mengetik alamat sendiri, bukan klik link",q:"Saat ingin memeriksa akun (bank, media sosial) karena menerima pesan mencurigakan, cara paling aman:",options:["Klik link di pesan untuk langsung memeriksa","Balas pesan itu menanyakan apakah benar dari mereka","Buka aplikasi resmi atau ketik alamat situsnya sendiri, bukan mengklik link dari pesan itu"],answer:2,explain:"Mengetik/membuka sendiri memastikan kamu benar-benar ke situs asli, bukan situs tiruan yang disamarkan lewat link.",hint:"Buka sendiri secara mandiri, atau klik link / balas pesan itu?"},
{n:43,type:"mcq",micro:"Verifikasi lewat kanal terpisah",q:"Kalau menerima permintaan uang mendesak dari 'kontak yang dikenal' lewat chat, cara verifikasi paling aman:",options:["Hubungi orang itu lewat cara lain yang sudah kamu kenal sebelumnya (telepon langsung ke nomor lama, tanya orang lain yang dekat dengannya)","Percaya karena namanya & fotonya cocok","Transfer sebagian dulu untuk 'jaga-jaga'"],answer:0,explain:"Kanal yang dipakai mengirim permintaan bisa saja sudah diretas/dipalsukan. Verifikasi lewat jalur lain yang independen lebih aman.",hint:"Verifikasi lewat kanal lain, atau percaya nama/foto / transfer sebagian?"},
{n:44,type:"mcq",micro:"Tidak memberi info di muka",q:"Prinsip umum yang aman: institusi/toko resmi yang sah biasanya...",options:["Tidak pernah berkomunikasi lewat pesan apa pun","Tidak meminta kamu membayar/memberi info sensitif SEBELUM kamu menerima layanan/barang/hadiah yang dijanjikan","Selalu meminta pembayaran penuh di muka tanpa jaminan"],answer:1,explain:"Kalau diminta 'bayar dulu baru dapat', terutama untuk hadiah yang katanya sudah kamu menangkan, itu pola mencurigakan.",hint:"Tidak minta bayar/info di muka untuk hal yang dijanjikan, atau selalu minta bayar dulu?"},
{n:45,type:"tf",micro:"Terlanjur klik link mencurigakan",q:"Benar atau Salah: Kalau terlanjur mengklik link mencurigakan, sebaiknya lanjutkan mengisi formulir di sana untuk 'melihat apa yang sebenarnya terjadi'.",answer:false,explain:"Sebaliknya, langkah amannya adalah menutup halaman tersebut & tidak memasukkan data apa pun di sana. Sekadar mengklik link belum tentu merugikan; yang paling berisiko adalah memasukkan data di halaman palsu.",hint:"Tutup & jangan isi data, atau lanjutkan mengisi untuk 'melihat apa yang terjadi'?"},
{n:46,type:"mcq",micro:"Setelah terlanjur memberi info sensitif",q:"Kalau terlanjur memasukkan kata sandi/data di situs yang ternyata palsu, langkah segera:",options:["Tidak melakukan apa-apa, berharap tidak terjadi apa-apa","Menghapus HP sepenuhnya","Ganti kata sandi akun terkait sesegera mungkin dari perangkat aman, & pantau aktivitas akun/keuangan"],answer:2,explain:"Mengganti kata sandi & memantau aktivitas segera mengurangi kerusakan yang bisa terjadi dari kebocoran data itu.",hint:"Ganti sandi & pantau segera, atau diamkan / hapus HP?"},
{n:47,type:"mcq",micro:"Melaporkan penipuan",q:"Setelah menyadari sesuatu adalah penipuan, langkah yang berguna bagi orang lain:",options:["Laporkan ke platform (fitur lapor) & beri tahu orang dewasa/kontak yang mungkin juga menjadi target","Diam saja karena 'sudah lewat, tidak penting lagi'","Membalas penipu dengan emosi untuk melampiaskan kekesalan"],answer:0,explain:"Melaporkan membantu platform menindak & bisa mencegah orang lain menjadi korban berikutnya.",hint:"Laporkan & beri tahu orang lain, atau diam / balas dengan emosi?"},
{n:48,type:"mcq",micro:"Memeriksa ulasan/reputasi penjual",q:"Sebelum membeli dari toko daring yang belum kamu kenal, kebiasaan yang bijak:",options:["Beli langsung dalam jumlah besar untuk hemat ongkir","Cek ulasan pembeli lain, lama toko beroperasi, & apakah ada yang melaporkan masalah sebelumnya","Percaya begitu saja karena harganya murah"],answer:1,explain:"Riwayat & ulasan memberi gambaran tentang keandalan penjual sebelum kamu mempertaruhkan uangmu.",hint:"Cek ulasan & riwayat, atau percaya karena murah / beli banyak?"},
{n:49,type:"mcq",micro:"Harga yang jauh di bawah wajar",q:"Barang mahal (HP baru, konsol game) dijual dengan harga jauh lebih murah dari pasaran tanpa alasan jelas, patut...",options:["Dianggap keberuntungan & segera dibeli tanpa cek apa pun","Selalu sah karena penjual sedang butuh uang","Dicurigai; harga yang terlalu jauh dari wajar sering tanda penipuan atau barang bermasalah"],answer:2,explain:"Selisih harga ekstrem tanpa penjelasan masuk akal adalah tanda bahaya klasik dalam jual-beli daring.",hint:"Dicurigai, atau dianggap keberuntungan?"},
{n:50,type:"order",micro:"Menghadapi permintaan uang mendadak",q:"Urutkan langkah menghadapi permintaan transfer uang mendadak dari 'kenalan' via chat.",items:["Jangan langsung transfer meski terasa mendesak","Cek apakah gaya bicara & detail terasa berbeda dari biasanya (tanda akun mungkin diretas)","Hubungi orang itu lewat panggilan telepon atau kanal lain untuk konfirmasi langsung","Bila terbukti penipuan, beri tahu orang itu (lewat kanal lain) agar mengamankan akunnya & peringatkan kontak lain"],answer:[0,1,2,3],explain:"Jangan transfer dulu → perhatikan kejanggalan → konfirmasi langsung → beri tahu & peringatkan. Konfirmasi harus lewat jalur berbeda dari yang dipakai meminta.",hint:"Menghubungi lewat kanal lain sebelum atau sesudah mencurigai kejanggalan gaya bicara?"},
{n:51,type:"mcq",micro:"Metode pembayaran yang lebih aman",q:"Untuk belanja daring dari penjual baru, metode yang memberi perlindungan lebih dibanding transfer langsung ke rekening pribadi:",options:["Sistem pembayaran resmi platform (rekening bersama/escrow, dompet digital resmi) yang menahan dana sampai barang diterima","Transfer tunai langsung ke rekening pribadi penjual tanpa jaminan apa pun","Membayar dengan menitipkan uang ke orang lain yang tidak dikenal"],answer:0,explain:"Sistem resmi platform biasanya menahan pembayaran sampai barang dikonfirmasi diterima, memberi jalan keluar bila terjadi masalah.",hint:"Sistem resmi yang menahan dana, atau transfer langsung tanpa jaminan?"},
{n:52,type:"tf",micro:"Rasa curiga tidak perlu bukti sempurna",q:"Benar atau Salah: Kamu harus 100% yakin sesuatu adalah penipuan sebelum boleh berhati-hati atau menunda bertindak.",answer:false,explain:"Sebaliknya, cukup ada beberapa tanda mencurigakan untuk memilih tidak bertindak dulu sampai yakin. Menunggu & memverifikasi tidak merugikan kalau ternyata sah, tapi bertindak cepat pada penipuan bisa sangat merugikan.",hint:"Cukup ada tanda mencurigakan untuk berhati-hati, atau harus 100% yakin dulu?"},
{n:53,type:"mcq",micro:"Menjaga info kartu/pembayaran",q:"Saat berbelanja daring, kebiasaan aman terkait info kartu pembayaran:",options:["Simpan info kartu di banyak situs untuk kemudahan","Hanya masukkan di situs resmi & tepercaya dengan koneksi aman (https), tidak pernah di situs yang mencurigakan","Masukkan di mana saja yang menawarkan diskon besar"],answer:1,explain:"Info kartu adalah data sangat sensitif. Hanya masukkan di tempat yang benar-benar tepercaya & sesedikit mungkin situs.",hint:"Hanya di situs resmi & tepercaya, atau di mana saja demi diskon?"},
{n:54,type:"mcq",micro:"Memeriksa keaslian aplikasi",q:"Sebelum memasang aplikasi 'resmi bank/pemerintah', cara memastikan keasliannya:",options:["Unduh dari link yang dikirim lewat pesan siapa pun","Percaya kalau ikonnya terlihat mirip","Unduh hanya dari toko aplikasi resmi & cek nama pengembang yang tertera cocok dengan lembaga aslinya"],answer:2,explain:"Aplikasi palsu bisa meniru ikon & nama. Memeriksa pengembang resmi & sumber unduhan mengurangi risiko memasang aplikasi berbahaya.",hint:"Toko resmi & cek pengembang, atau link sembarangan / percaya ikon?"},
{n:55,type:"mcq",micro:"Menahan diri dari rasa malu melapor",q:"Kalau kamu (atau orang terdekat) terlanjur tertipu, rasa malu sering membuat orang tidak melapor. Sikap yang lebih baik:",options:["Tetap laporkan & cari bantuan; rasa malu tidak sebanding dengan manfaat mencegah kerugian lebih lanjut & membantu orang lain","Diam selamanya karena malu","Menyalahkan diri sendiri tanpa mengambil tindakan"],answer:0,explain:"Banyak orang tertipu, bahkan yang berpengalaman. Melapor cepat bisa membantu memulihkan sebagian kerugian & mencegah korban lain.",hint:"Tetap laporkan meski malu, atau diam / hanya menyalahkan diri?"},
{n:56,type:"tf",micro:"Penipuan bisa terjadi di aplikasi apa pun",q:"Benar atau Salah: Penipuan hanya terjadi lewat email, jadi kewaspadaan di chat, media sosial, marketplace, atau game tidak begitu perlu.",answer:false,explain:"Sebaliknya, penipuan bisa muncul di berbagai jenis aplikasi, bukan hanya email. Kewaspadaan perlu diterapkan di semua platform yang kamu pakai.",hint:"Bisa di berbagai platform, atau hanya email?"},
{n:57,type:"mcq",micro:"Menjaga anggota keluarga rentan",q:"Kakek/nenek atau anggota keluarga yang kurang paham teknologi bisa dibantu dengan...",options:["Melarang mereka memakai internet sama sekali","Mengajarkan tanda-tanda penipuan umum & menyepakati 'kalau ragu, tanya dulu ke keluarga sebelum bertindak'","Membiarkan mereka belajar sendiri dari pengalaman buruk"],answer:1,explain:"Edukasi & kesepakatan sederhana ('tanya dulu sebelum transfer/klik') lebih membantu daripada membiarkan atau melarang total.",hint:"Ajarkan & sepakati 'tanya dulu', atau biarkan belajar sendiri / larang total?"},
{n:58,type:"mcq",micro:"Menyimpan bukti",q:"Kalau menemukan percobaan penipuan (pesan, tautan), kebiasaan yang berguna:",options:["Langsung hapus tanpa menyimpan apa pun","Membalas & berdebat dengan penipunya","Simpan tangkapan layar sebagai bukti sebelum memblokir/menghapus, berguna untuk laporan"],answer:2,explain:"Bukti (tangkapan layar) membantu proses pelaporan ke platform atau pihak berwenang, & bisa dipakai memperingatkan orang lain.",hint:"Simpan bukti dulu, atau hapus langsung / berdebat?"},
{n:59,type:"mcq",micro:"Waspada tapi tidak paranoid",q:"Sikap yang seimbang terhadap risiko penipuan online:",options:["Waspada & memeriksa hal yang mencurigakan, tanpa menjadi takut berlebihan pada semua interaksi daring","Curiga pada semua orang & semua pesan tanpa kecuali","Percaya semua pesan tanpa pernah memeriksa"],answer:0,explain:"Kewaspadaan yang proporsional memungkinkan kita tetap menikmati & mempercayai interaksi daring yang wajar, sambil siap pada tanda bahaya nyata.",hint:"Waspada proporsional, atau curiga semua / percaya semua?"},
{n:60,type:"open",micro:"Rencana pribadi menghadapi penipuan",q:"Buat rencana pribadi menghadapi kemungkinan penipuan online. Sertakan: (a) 3 tanda bahaya yang akan selalu membuatmu waspada, (b) aturan pribadi soal kapan kamu TIDAK AKAN pernah memberi info/uang tanpa verifikasi, (c) langkah yang akan kamu ambil bila menemukan percobaan penipuan yang menyasarmu, (d) bagaimana kamu akan membantu anggota keluarga yang mungkin lebih rentan.",sample:"(a) Tanda bahaya yang selalu membuatku waspada: (1) Diminta membayar/mengirim uang atau info sensitif dengan mendesak. (2) Tawaran hadiah/untung besar yang tidak masuk akal atau yang tidak pernah kuikuti. (3) Diminta memberi kode OTP, kata sandi, atau data kartu lewat pesan/telepon siapa pun. (b) Aturan pribadi: aku tidak akan pernah mengirim uang atau info sensitif hanya berdasarkan pesan/telepon, tanpa memverifikasi lewat kanal lain yang sudah kukenal sebelumnya, bahkan kalau itu terlihat dari orang yang kukenal & terasa sangat mendesak, aku tetap akan mencari cara memastikan lebih dulu. (c) Langkah bila menjadi target: aku tidak akan membalas atau mengklik apa pun; aku akan menyimpan bukti (tangkapan layar), memblokir & melaporkan lewat fitur resmi platform, & memberi tahu orang dewasa tepercaya bila melibatkan uang atau data penting. Kalau terlanjur memasukkan info sensitif, aku akan segera mengganti kata sandi terkait & memantau aktivitas akun. (d) Membantu keluarga rentan: aku akan sesekali mengobrol santai dengan kakek/nenek atau anggota keluarga lain tentang contoh penipuan terbaru yang kudengar, mengajak mereka menyepakati 'kalau ada yang minta transfer atau data mendesak, telepon dulu salah satu dari kita sebelum bertindak', & menyimpan nomor keluarga terdekat dengan mudah diakses di HP mereka.",explain:"Jawaban baik: 3 tanda bahaya yang spesifik & mencakup pola berbeda (urgensi, tawaran tak masuk akal, permintaan info sensitif), aturan pribadi yang tegas & konkret (bukan 'akan lebih hati-hati'), langkah respons yang berurutan & benar untuk dirinya sendiri, & rencana konkret membantu anggota keluarga yang lebih rentan.",hint:"Bagian (b) harus berupa aturan yang benar-benar tegas ('tidak akan PERNAH...'), bukan sekadar niat umum untuk berhati-hati."},

// FASE D — PENALARAN (61-80): jenis spesifik, melindungi orang lain
{n:61,type:"mcq",micro:"Kenapa siapa saja bisa tertipu",q:"Penting dipahami bahwa tertipu penipuan online BUKAN tanda seseorang bodoh, karena...",options:["Penipuan hanya berhasil kalau korbannya memang tidak berpendidikan","Penipu profesional merancang taktiknya secara khusus untuk memanfaatkan kelemahan psikologi manusia yang wajar, siapa pun bisa terkena di momen lengah","Hanya orang bodoh yang bisa tertipu"],answer:1,explain:"Menyalahkan korban ('harusnya kamu lebih pintar') tidak membantu & tidak akurat. Siapa pun bisa lengah di momen sibuk, lelah, atau emosional.",hint:"Bisa terjadi pada siapa saja di momen lengah, atau hanya orang bodoh?"},
{n:62,type:"mcq",micro:"Dukungan tanpa menyalahkan",q:"Kalau temanmu bercerita bahwa dia tertipu penipuan online, respons yang membantu:",options:["Menertawakannya karena 'harusnya sudah tahu'","Menceritakan ke orang lain sebagai bahan gosip","Dengarkan tanpa menghakimi, bantu memikirkan langkah selanjutnya (lapor, ganti sandi, dll), bukan menyalahkan 'kok bisa sih'"],answer:2,explain:"Dukungan yang tidak menghakimi membuat orang lebih terbuka mencari bantuan lebih cepat, mengurangi kerugian yang bisa terjadi.",hint:"Dengarkan & bantu tanpa menghakimi, atau menertawakan / gosipkan?"},
{n:63,type:"mcq",micro:"Penipuan berevolusi seiring waktu",q:"Kenapa penting terus memperbarui pemahaman tentang jenis-jenis penipuan?",options:["Taktik penipu terus berubah mengikuti teknologi & tren baru, jadi contoh lama saja tidak cukup untuk mengenali yang baru","Semua jenis penipuan sudah ditemukan & tidak akan berubah lagi","Penipuan hanya ada satu jenis yang sama dari dulu"],answer:0,explain:"Sama seperti keamanan siber lainnya, ini bidang yang terus berkembang. Kebiasaan mengenali POLA (bukan hanya contoh spesifik) lebih tahan lama.",hint:"Taktik terus berubah, atau semua sudah tetap sama?"},
{n:64,type:"tf",micro:"Penipuan menargetkan kerentanan spesifik",q:"Benar atau Salah: Penipu sering menyesuaikan taktiknya dengan kerentanan target tertentu, misalnya kesepian, kebutuhan uang mendesak, atau kecintaan pada game/idola.",answer:true,explain:"Memahami ini membantu kita mengenali kapan kita sendiri sedang berada dalam kondisi yang membuat kita lebih rentan (kesepian, butuh uang, sangat ingin sesuatu).",hint:"Menyesuaikan dengan kerentanan target, atau memakai satu cara sama untuk semua?"},
{n:65,type:"mcq",micro:"Penipuan & kesepian",q:"Kenapa orang yang merasa kesepian atau kurang perhatian bisa lebih rentan pada penipuan 'hubungan daring palsu'?",options:["Tidak ada hubungan antara kesepian & kerentanan","Perhatian & kedekatan yang ditawarkan (meski palsu) terasa sangat berharga, membuat tanda bahaya lebih mudah diabaikan","Orang kesepian selalu lebih pintar mengenali penipuan"],answer:1,explain:"Memahami kerentanan emosional ini (tanpa menyalahkan korban) membantu kita lebih peka pada diri sendiri & orang di sekitar.",hint:"Perhatian palsu terasa berharga hingga tanda bahaya diabaikan, atau tak ada hubungan?"},
{n:66,type:"mcq",micro:"Penipuan berbasis tren/berita terkini",q:"Penipu sering memanfaatkan peristiwa besar (bencana, tren viral, rilis produk baru) untuk membuat penipuan karena...",options:["Peristiwa besar membuat orang otomatis lebih waspada","Tidak ada hubungan antara tren & penipuan","Orang sedang sangat memperhatikan topik itu, sehingga penipuan bertema serupa terasa relevan & kurang dicurigai"],answer:2,explain:"Penipuan donasi bencana palsu atau 'pre-order' produk baru palsu adalah contoh memanfaatkan momentum perhatian publik.",hint:"Memanfaatkan perhatian pada topik hangat, atau membuat orang otomatis waspada?"},
{n:67,type:"mcq",micro:"Melindungi data yang bisa dipakai menipu orang lain",q:"Kalau akunmu sendiri diretas, penipu bisa memakainya untuk menipu kontak-kontakmu. Ini artinya menjaga akunmu tetap aman juga...",options:["Melindungi orang-orang di sekitarmu, bukan hanya dirimu sendiri","Hanya melindungi dirimu, tidak berhubungan dengan orang lain","Tidak ada hubungannya dengan penipuan sama sekali"],answer:0,explain:"Rantai kepercayaan berarti akunmu yang aman melindungi orang yang mempercayai pesan darimu dari penipuan yang mengatasnamakanmu.",hint:"Melindungi orang lain juga, atau hanya diri sendiri?"},
{n:68,type:"tf",micro:"Verifikasi tidak berarti tidak percaya orang",q:"Benar atau Salah: Memverifikasi permintaan uang/info yang tampak dari orang yang dikenal tidak berarti kamu tidak mempercayai orang itu; itu kebiasaan yang wajar terhadap SEMUA permintaan semacam itu.",answer:true,explain:"Sama seperti memeriksa fakta, verifikasi adalah kebiasaan terhadap situasi, bukan tuduhan terhadap karakter orangnya.",hint:"Bukan berarti tidak percaya orangnya, atau selalu tanda curiga pada orang itu?"},
{n:69,type:"mcq",micro:"Menyeimbangkan kepercayaan & kehati-hatian daring",q:"Membangun hubungan & kepercayaan yang sehat secara daring tetap mungkin dengan cara...",options:["Tidak pernah berinteraksi dengan siapa pun secara daring","Membangun kepercayaan secara bertahap, tetap waspada pada permintaan uang/info sensitif, & memverifikasi hal penting","Mempercayai semua orang sepenuhnya sejak awal"],answer:1,explain:"Kepercayaan yang sehat dibangun bertahap, bukan diberikan penuh sejak awal, terutama menyangkut uang atau info sensitif.",hint:"Bangun bertahap & tetap waspada, atau percaya penuh sejak awal / hindari total?"},
{n:70,type:"tf",micro:"Kerugian dari penipuan bukan hanya uang",q:"Benar atau Salah: Selain kerugian uang, penipuan online bisa berdampak emosional (malu, marah, kehilangan kepercayaan) yang juga penting diakui & ditangani.",answer:true,explain:"Dukungan emosional untuk korban penipuan sama pentingnya dengan bantuan praktis (lapor, ganti sandi), karena dampaknya bukan hanya finansial.",hint:"Ada dampak emosional juga, atau hanya soal uang?"},
{n:71,type:"mcq",micro:"Penipuan yang menyasar niat baik",q:"Penipuan donasi palsu (mengaku untuk bencana/amal) sangat merugikan karena...",options:["Tidak ada dampak selain kerugian uang si penyumbang","Selalu mudah dikenali sehingga tidak berbahaya","Memanfaatkan niat baik orang & bisa membuat orang jadi ragu menyumbang ke yang benar-benar membutuhkan di masa depan"],answer:2,explain:"Selain merugikan langsung, penipuan semacam ini merusak kepercayaan pada donasi sah, yang pada akhirnya merugikan orang yang benar-benar butuh bantuan.",hint:"Merusak kepercayaan pada donasi sah juga, atau hanya rugi uang?"},
{n:72,type:"mcq",micro:"Menilai lembaga donasi",q:"Sebelum menyumbang untuk sebuah bencana/kejadian, cara memastikan lembaganya sah:",options:["Cek apakah lembaga itu resmi terdaftar & terverifikasi, & salurkan lewat kanal resminya, bukan lewat rekening pribadi yang diklaim 'untuk disalurkan'","Percaya siapa saja yang meminta atas nama korban bencana","Menyumbang ke rekening pribadi yang dibagikan di grup chat"],answer:0,explain:"Lembaga resmi biasanya bisa diverifikasi & punya jalur donasi resmi. Rekening pribadi tanpa verifikasi berisiko disalahgunakan.",hint:"Cek lembaga resmi & kanal resmi, atau percaya rekening pribadi sembarangan?"},
{n:73,type:"mcq",micro:"Penipuan & tekanan teman sebaya",q:"Kalau teman-temanmu ikut sebuah 'peluang' yang terlihat mencurigakan & mengajakmu ikut juga, sikap yang bijak:",options:["Langsung menuduh teman-temanmu bodoh","Tetap periksa sendiri dengan kritis; ikut-ikutan bukan bukti bahwa sesuatu itu aman","Ikut saja karena teman-teman sudah mencobanya duluan"],answer:1,explain:"'Banyak yang ikut' bukan jaminan keamanan, kadang justru tanda skema yang sedang menyebar cepat sebelum runtuh. Tetap nilai sendiri.",hint:"Tetap periksa sendiri, atau ikut karena teman / menuduh mereka?"},
{n:74,type:"mcq",micro:"Penipuan & rasa gengsi",q:"Kalau kamu ragu tentang sesuatu tapi malu bertanya karena takut terlihat 'tidak update/gaptek', sikap yang lebih bijak:",options:["Berpura-pura paham & ikut saja","Diam & berharap yang terbaik","Tetap bertanya atau memeriksa; rasa malu sesaat jauh lebih ringan daripada kerugian akibat penipuan"],answer:2,explain:"Gengsi sering membuat orang tidak bertanya di saat yang paling penting untuk bertanya. Keselamatan lebih penting daripada terlihat 'tahu segalanya'.",hint:"Tetap bertanya meski malu, atau berpura-pura paham / diam?"},
{n:75,type:"order",micro:"Membantu korban penipuan (bukan diri sendiri)",q:"Urutkan langkah membantu seseorang yang baru saja sadar tertipu.",items:["Dengarkan tanpa menyalahkan & pastikan mereka merasa aman bercerita","Bantu mengambil langkah segera (ganti kata sandi, hubungi bank bila menyangkut uang)","Bantu melaporkan ke platform/pihak berwenang yang relevan","Ajak merefleksikan bersama apa yang bisa dikenali lain kali, tanpa menghakimi"],answer:[0,1,2,3],explain:"Dengarkan & buat aman → tindakan segera → laporkan → refleksi bersama. Refleksi datang terakhir, setelah kerusakan ditangani & orangnya merasa didukung.",hint:"Merefleksikan pelajaran dilakukan di awal atau setelah langkah segera & pelaporan?"},
{n:76,type:"tf",micro:"Penipuan bisa dicegah dengan kebiasaan sederhana",q:"Benar atau Salah: Sebagian besar penipuan online bisa dicegah dengan kebiasaan sederhana: jeda sebelum bertindak, verifikasi lewat kanal lain, & tidak memberi info sensitif tanpa yakin.",answer:true,explain:"Penipuan sering mengandalkan reaksi cepat & kurang verifikasi. Kebiasaan dasar ini sudah menutup sebagian besar celah yang dimanfaatkan.",hint:"Bisa dicegah dengan kebiasaan sederhana, atau butuh keahlian teknis tinggi?"},
{n:77,type:"mcq",micro:"Penipuan menargetkan siapa yang aktif online",q:"Semakin banyak & lama seseorang aktif di berbagai platform daring, semakin...",options:["Besar juga kemungkinan bertemu percobaan penipuan, jadi kebiasaan waspada makin penting seiring aktivitas bertambah","Kecil kemungkinan bertemu penipuan","Tidak ada hubungan antara aktivitas & risiko"],answer:0,explain:"Lebih banyak interaksi daring berarti lebih banyak peluang bertemu penipu, sehingga kebiasaan waspada perlu jadi bagian rutin, bukan sesekali.",hint:"Makin besar kemungkinan bertemu penipuan, atau makin kecil?"},
{n:78,type:"mcq",micro:"Penipuan & tanggung jawab platform",q:"Selain tanggung jawab individu, platform (media sosial, marketplace) juga punya peran dalam mencegah penipuan lewat...",options:["Menjamin 100% tidak akan ada penipuan di platform mereka","Fitur pelaporan, verifikasi akun, & sistem pembayaran yang aman, meski tetap tidak bisa mencegah semuanya","Tidak punya peran sama sekali, semua tanggung jawab pengguna"],answer:1,explain:"Tanggung jawab berbagi: individu waspada, platform menyediakan alat & sistem yang mengurangi risiko, meski tidak sempurna.",hint:"Platform juga berperan lewat fitur & sistem, atau sepenuhnya tanggung jawab individu / jaminan sempurna?"},
{n:79,type:"mcq",micro:"Kesadaran tanpa ketakutan berlebihan",q:"Tujuan mempelajari pola penipuan online adalah...",options:["Membuat kita berhenti memakai internet sama sekali","Membuat kita curiga pada setiap orang yang kita temui daring","Membuat kita lebih siap & tenang menghadapi situasi mencurigakan, bukan membuat kita takut memakai internet"],answer:2,explain:"Kesiapan menggantikan ketakutan dengan kompetensi, kita tahu apa yang harus dilakukan, bukan panik atau menghindar sepenuhnya.",hint:"Membuat lebih siap & tenang, atau membuat takut / curiga berlebihan?"},
{n:80,type:"open",micro:"Skema penipuan & cara memutusnya",q:"Bayangkan sebuah skema: orang tak dikenal di media sosial menawarimu 'jadi reseller' produk dengan untung sangat besar, tapi kamu harus membeli stok awal senilai jutaan rupiah dulu tanpa boleh melihat produknya langsung. Analisis: (a) tanda-tanda kecurigaan, (b) pertanyaan yang akan kamu ajukan untuk menguji kewajaran tawaran ini, (c) bagaimana kamu akan menolak dengan sopan tapi tegas, (d) bagaimana kamu akan memperingatkan teman yang mungkin tergiur skema serupa.",sample:"(a) Tanda kecurigaan: (1) Diminta membeli stok besar di muka sebelum benar-benar melihat/mencoba produknya, risiko finansial besar di awal tanpa jaminan. (2) Janji untung 'sangat besar' yang tidak proporsional dengan usaha atau modal, mirip pola skema cepat kaya. (3) Tidak jelas siapa produsen aslinya, tidak ada cara memverifikasi produk atau perusahaan secara independen. (b) Pertanyaan untuk menguji kewajaran: 'Bolehkah saya melihat/mencoba produknya dulu sebelum membeli stok besar?' 'Apakah ada testimoni pembeli asli yang bisa saya hubungi langsung, bukan hanya yang ditunjukkan mereka?' 'Bagaimana kalau saya mulai dengan jumlah sangat kecil dulu untuk mencoba?' 'Apa nama perusahaan resminya & bisakah saya cek keberadaannya secara independen (bukan hanya dari mereka)?' (c) Menolak dengan sopan tapi tegas: 'Terima kasih infonya, tapi aku belum nyaman membeli stok sebesar itu tanpa bisa mengeceknya lebih dulu. Mungkin lain kali kalau ada cara mencoba dalam jumlah kecil dulu.' lalu tidak melanjutkan komunikasi kalau terus didesak. (d) Memperingatkan teman: aku akan bercerita dengan tenang (bukan menggurui), 'Eh, aku pernah ditawarin hal mirip, coba deh perhatikan apakah mereka mau kamu lihat produknya dulu sebelum beli stok besar, & coba cari tahu perusahaannya sendiri, jangan cuma percaya dari yang mereka kasih tahu' supaya temanku bisa menilai sendiri dengan pertanyaan yang sama, bukan sekadar aku bilang 'itu penipuan, jangan ikut'.",explain:"Jawaban baik: 3 tanda kecurigaan yang spesifik pada skema reseller/investasi (risiko di muka, untung tak proporsional, tak bisa diverifikasi independen), pertanyaan-pertanyaan yang benar-benar bisa menguji kewajaran tawaran, penolakan yang sopan namun tegas, & cara memperingatkan teman yang mengajarkan cara berpikir (bukan sekadar melarang), sehingga teman bisa menilai sendiri di kesempatan lain.",hint:"Bagian (d) sebaiknya mengajarkan CARA MENILAI, bukan hanya kesimpulan 'itu penipuan', karena itu lebih membekali temanmu untuk situasi berikutnya."},

// FASE E — TANTANGAN (81-100): skenario & kapstone
{n:81,type:"mcq",micro:"Skenario: pesan mengaku dari layanan streaming",q:"Pesan 'Akun streamingmu bermasalah, update metode pembayaran sekarang lewat link ini' tiba-tiba muncul padahal kamu tidak berlangganan layanan itu. Langkah tepat:",options:["Abaikan/hapus; kalau kamu tidak berlangganan layanan itu, pesan itu jelas tidak relevan & mencurigakan","Klik untuk melihat apa yang terjadi","Balas untuk memberi tahu bahwa kamu tidak berlangganan"],answer:0,explain:"Ketidaksesuaian mendasar (tidak berlangganan tapi diminta update pembayaran) adalah tanda paling jelas bahwa pesan ini tidak sah.",hint:"Abaikan/hapus, atau klik / balas?"},
{n:82,type:"mcq",micro:"Skenario: teman minta pinjam saldo game",q:"Teman sekelasmu (yang jarang bicara) tiba-tiba chat minta kamu membelikan voucher game 'nanti diganti besok di sekolah'. Sikap yang bijak:",options:["Tolak mentah-mentah tanpa konfirmasi apa pun","Tanyakan langsung secara tatap muka atau telepon untuk memastikan itu benar dia yang meminta, bukan akunnya yang diretas","Langsung belikan karena sudah kenal orangnya"],answer:1,explain:"Permintaan mendadak & tidak biasa dari kenalan yang jarang bicara patut dikonfirmasi lewat cara lain sebelum bertindak.",hint:"Konfirmasi lewat cara lain, atau langsung beli / tolak tanpa cek?"},
{n:83,type:"mcq",micro:"Skenario: hadiah dari brand favoritmu",q:"Akun yang mengaku brand favoritmu (tapi centang verifikasinya tidak ada/berbeda dari akun resminya) menawarkan hadiah eksklusif lewat DM. Langkah:",options:["Percaya karena namanya sama dengan brand favoritmu","Langsung ikuti instruksi di DM tersebut","Cek akun resmi brand itu langsung (dari sumber yang kamu ketik sendiri) untuk memastikan promo ini benar ada, jangan percaya DM begitu saja"],answer:2,explain:"Nama & logo mudah ditiru. Verifikasi lewat sumber resmi yang kamu cari sendiri lebih dapat diandalkan daripada pesan yang masuk.",hint:"Cek sumber resmi sendiri, atau percaya nama / ikuti instruksi DM?"},
{n:84,type:"mcq",micro:"Skenario: penipuan menyasar orang tua",q:"Kamu melihat orang tuamu hampir mentransfer uang karena telepon yang mengaku 'polisi' bilang anaknya (kamu) tertangkap masalah & butuh uang tebusan segera. Langkah cepat & tepat:",options:["Segera hubungi/tunjukkan diri secara langsung ke orang tua untuk membuktikan kamu baik-baik saja, sebelum transfer dilakukan","Biarkan orang tua tetap transfer dulu untuk jaga-jaga","Diam saja karena bukan urusanmu"],answer:0,explain:"Ini modus penipuan umum yang menyasar orang tua lewat rasa panik akan keselamatan anak. Membuktikan diri langsung menghentikan penipuan seketika.",hint:"Tunjukkan diri langsung untuk membuktikan aman, atau biarkan transfer / diam?"},
{n:85,type:"tf",micro:"Kewaspadaan adalah keterampilan yang tumbuh",q:"Benar atau Salah: Kemampuan mengenali & menghindari penipuan online adalah keterampilan yang bisa terus diasah, & wajar melakukan kesalahan saat masih belajar mengenalinya.",answer:true,explain:"Seperti keterampilan lain, semakin sering berlatih mengenali pola, semakin cepat & alami kewaspadaan itu bekerja.",hint:"Keterampilan yang bisa diasah & wajar salah saat belajar, atau harus langsung sempurna?"},
{n:86,type:"mcq",micro:"Skenario: penawaran kerja sampingan online",q:"Ada tawaran 'kerja sampingan online, cukup like & subscribe video, gaji harian langsung cair' yang meminta 'deposit awal' untuk mulai. Analisis cepat:",options:["Aman selama gajinya terlihat besar","Mencurigakan; pekerjaan sah tidak meminta pekerja membayar deposit untuk mulai bekerja","Wajar karena semua pekerjaan online butuh modal awal"],answer:1,explain:"Arah uang yang terbalik (pekerja membayar, bukan dibayar untuk memulai) adalah tanda klasik penipuan kerja sampingan daring.",hint:"Mencurigakan karena arah uang terbalik, atau wajar / aman karena gaji besar?"},
{n:87,type:"mcq",micro:"Skenario: mengecek keaslian sebuah situs belanja",q:"Kamu menemukan situs belanja baru dengan diskon sangat besar untuk barang branded. Langkah cepat mengecek keaslian:",options:["Langsung beli karena diskonnya menarik","Percaya karena tampilan situsnya profesional","Cari nama situsnya + kata 'penipuan' atau 'review' di mesin pencari, & cek apakah ada kontak & alamat yang jelas serta bisa diverifikasi"],answer:2,explain:"Tampilan profesional mudah ditiru. Pencarian ulasan dari pihak luar & pengecekan kontak/alamat memberi gambaran lebih akurat.",hint:"Cari ulasan luar & cek kontak, atau percaya tampilan / diskon?"},
{n:88,type:"mcq",micro:"Skenario: temanmu hampir tertipu",q:"Kamu melihat temanmu di sekolah hampir memberikan kata sandi akun game ke situs 'penukar item' yang mencurigakan. Sikap yang membantu:",options:["Tunjukkan tanda-tanda mencurigakannya dengan tenang & jelaskan risikonya, bukan hanya bilang 'jangan!' tanpa alasan","Membiarkannya mencoba sendiri supaya 'belajar dari pengalaman'","Mengejeknya karena hampir tertipu"],answer:0,explain:"Menjelaskan ALASAN (bukan hanya melarang) membantu temanmu belajar mengenali pola serupa di masa depan sendiri.",hint:"Jelaskan alasan dengan tenang, atau biarkan / ejek?"},
{n:89,type:"mcq",micro:"Skenario: menyeimbangkan efisiensi & keamanan belanja",q:"Kamu terburu-buru butuh membeli sesuatu & menemukan toko baru dengan harga bagus tapi belum sempat kamu cek ulasannya. Sikap yang bijak:",options:["Batalkan seluruh rencana membeli apa pun secara daring","Kalau memang penting & mendesak, cari toko resmi/tepercaya yang sudah dikenal meski sedikit lebih mahal, daripada mengambil risiko di toko yang belum terverifikasi","Beli saja karena terburu-buru, tidak sempat cek apa pun"],answer:1,explain:"Ketergesaan bukan alasan mengabaikan keamanan. Memilih yang sudah terverifikasi meski sedikit lebih mahal sering lebih bijak daripada berjudi dengan toko baru.",hint:"Pilih yang terverifikasi meski sedikit mahal, atau beli buru-buru tanpa cek / batalkan total?"},
{n:90,type:"order",micro:"Proyek: kampanye kesadaran anti-penipuan",q:"Urutkan langkah membuat kampanye kesadaran anti-penipuan sederhana untuk kelas/keluarga.",items:["Kumpulkan 3-5 contoh penipuan nyata yang pernah dialami/didengar di sekitarmu","Identifikasi pola & tanda bahaya yang sama di semua contoh itu","Buat panduan singkat (poster/pesan) berisi tanda bahaya & langkah aman","Bagikan & diskusikan bersama, kumpulkan cerita/pertanyaan baru untuk memperbaiki panduan"],answer:[0,1,2,3],explain:"Kumpulkan contoh nyata → cari pola bersama → buat panduan → bagikan & perbaiki. Contoh nyata dari lingkungan sendiri membuatnya lebih relevan & mudah diingat.",hint:"Mengidentifikasi pola bersama sebelum atau sesudah mengumpulkan contoh nyata?"},
{n:91,type:"mcq",micro:"Skenario: tekanan waktu ekstrem",q:"Sebuah pesan memberi waktu hanya 5 menit untuk 'menyelamatkan akunmu'. Kamu merasa sangat panik. Langkah paling penting saat itu:",options:["Bertindak sesuai instruksi karena waktunya sangat mepet","Menutup HP sepenuhnya tanpa memeriksa apa pun","Sadari bahwa tekanan waktu ekstrem itu sendiri adalah tanda bahaya; tarik napas, jangan bertindak dalam panik, & verifikasi dulu"],answer:2,explain:"Mengenali tekanan waktu ekstrem SEBAGAI tanda bahaya (bukan alasan buru-buru) adalah kunci menahan diri dari jebakan ini.",hint:"Kenali tekanan waktu sebagai tanda bahaya & verifikasi, atau ikuti instruksi / abaikan semua tanpa periksa?"},
{n:92,type:"tf",micro:"Melawan penipuan adalah usaha bersama",q:"Benar atau Salah: Semakin banyak orang yang mengenali & tidak mempan pada taktik penipuan tertentu, semakin kecil keuntungan bagi penipu untuk terus memakai taktik itu.",answer:true,explain:"Penipuan bertahan karena cukup berhasil pada sebagian orang. Kesadaran kolektif yang meluas mengurangi efektivitas taktik lama, mendorong perlunya kewaspadaan terus berkembang.",hint:"Kesadaran kolektif mengurangi keuntungan penipu, atau tidak berpengaruh?"},
{n:93,type:"mcq",micro:"Skenario: menyeimbangkan waspada & tetap ramah",q:"Kamu jadi lebih waspada setelah belajar tentang penipuan, tapi tidak ingin jadi orang yang selalu curiga pada semua orang baru. Cara menyeimbangkannya:",options:["Tetap ramah & terbuka pada interaksi biasa, tapi menerapkan kehati-hatian khusus HANYA saat menyangkut uang, data sensitif, atau permintaan yang tidak biasa","Curiga pada semua orang baru tanpa kecuali","Berhenti waspada sama sekali demi tetap ramah"],answer:0,explain:"Kewaspadaan bisa dipersempit ke situasi yang benar-benar berisiko (uang, data, permintaan aneh), sehingga tetap bisa ramah dalam interaksi sehari-hari.",hint:"Waspada khusus pada situasi berisiko, atau curiga semua / tak waspada sama sekali?"},
{n:94,type:"mcq",micro:"Skenario: menemukan penipuan yang menyasar sekolah",q:"Kamu menemukan pesan penipuan yang mengatasnamakan sekolahmu beredar ke banyak orang tua. Langkah yang bertanggung jawab:",options:["Menyebarkan lebih lanjut ke banyak grup untuk 'memperingatkan'","Beri tahu pihak sekolah secepatnya supaya mereka bisa mengklarifikasi resmi ke semua orang tua","Diam saja karena bukan urusanmu"],answer:1,explain:"Pihak sekolah punya wewenang & jangkauan resmi untuk mengklarifikasi ke semua pihak terkait dengan cara yang tepercaya.",hint:"Beri tahu sekolah untuk klarifikasi resmi, atau diam / sebar lebih lanjut sendiri?"},
{n:95,type:"tf",micro:"Kompetensi mengalahkan ketakutan",q:"Benar atau Salah: Tujuan akhir mempelajari topik ini adalah membuat kita kompeten menghadapi situasi mencurigakan dengan tenang, bukan membuat kita hidup dalam rasa takut terus-menerus.",answer:true,explain:"Rasa takut yang melumpuhkan tidak produktif. Kompetensi (tahu tanda bahaya & langkah yang tepat) membuat kita bisa tetap tenang & bertindak benar.",hint:"Kompetensi & tenang, atau takut terus-menerus?"},
{n:96,type:"mcq",micro:"Skenario: menerima permintaan pertemanan mencurigakan berulang",q:"Kamu terus menerima permintaan pertemanan dari akun-akun baru yang mirip satu sama lain (foto profil menarik, sedikit unggahan). Sikap yang bijak:",options:["Terima semua supaya jumlah temanmu banyak","Terima satu untuk 'mencoba melihat apa maunya'","Tolak atau abaikan; pola berulang seperti ini sering dipakai untuk penipuan/pengumpulan target massal"],answer:2,explain:"Pola akun serupa yang berulang adalah tanda operasi penipuan massal. Tidak perlu mengambil risiko untuk 'melihat apa maunya'.",hint:"Tolak/abaikan pola berulang, atau terima demi jumlah teman / coba lihat maksudnya?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup mahir mengenali & menghindari penipuan online:",options:["Kamu mengenali pola dasar (urgensi, janji besar, minta info sensitif), tahu cara verifikasi, & tahu langkah bila terlanjur tertipu","Kamu hafal daftar nama penipuan tapi tetap panik & langsung bertindak saat menemuinya","Kamu berhenti berinteraksi dengan siapa pun secara daring"],answer:0,explain:"Kemahiran sejati terlihat dari respons tenang & tepat saat menghadapi situasi nyata, bukan sekadar hafalan atau menghindar total.",hint:"Kenali pola, tahu verifikasi, tahu langkah bila tertipu, atau hafal tanpa tenang / hindari total?"},
{n:98,type:"mcq",micro:"Penipuan & masyarakat digital yang sehat",q:"Masyarakat dengan kesadaran anti-penipuan yang tinggi cenderung...",options:["Tidak berpengaruh pada kualitas interaksi digital","Lebih sulit dieksploitasi & lebih saling membantu saat ada yang berpotensi jadi korban","Menjadi tempat yang tidak ramah & penuh curiga"],answer:1,explain:"Kesadaran kolektif membuat komunitas lebih tangguh terhadap eksploitasi, sekaligus tetap bisa saling percaya dalam interaksi yang wajar.",hint:"Lebih sulit dieksploitasi & saling membantu, atau tidak ramah / tak berpengaruh?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'penipuan online & phishing':",options:["Percaya semua orang yang berinteraksi denganmu secara daring","Menghindari semua interaksi & transaksi daring sepenuhnya","Kenali pola manipulasi (urgensi, janji berlebihan, minta info sensitif), jeda sebelum bertindak, verifikasi lewat kanal terpisah, & tahu langkah bila terlanjur tertipu"],answer:2,explain:"Kenali pola + jeda + verifikasi + tahu langkah pemulihan. Kombinasi ini membuat kita siap tanpa harus menghindari manfaat dunia digital.",hint:"Kenali pola + jeda + verifikasi + tahu langkah, atau percaya semua / hindari semua?"},
{n:100,type:"open",micro:"Kapstone: panduan anti-penipuan pribadi",q:"Buat 'panduan anti-penipuan' pribadimu. Sertakan: (a) 5 tanda bahaya utama yang akan selalu kamu waspadai, (b) 3 aturan pribadi tegas (hal yang tidak akan pernah kamu lakukan tanpa verifikasi), (c) langkah berurutan yang akan kamu ambil saat menemui percobaan penipuan, (d) langkah pemulihan bila terlanjur tertipu, (e) bagaimana kamu akan membantu melindungi orang lain di sekitarmu (keluarga, teman) dari penipuan.",sample:"(a) 5 tanda bahaya: (1) Ada tekanan waktu ekstrem untuk segera bertindak. (2) Diminta memberi kata sandi, kode OTP, atau data kartu lewat pesan/telepon. (3) Janji untung/hadiah besar yang tidak proporsional dengan usaha atau yang tidak pernah kuikuti. (4) Diminta membayar/transfer sebelum menerima layanan/barang/hadiah yang dijanjikan. (5) Identitas pengirim tidak bisa diverifikasi (nomor baru, akun baru, alamat email aneh) tapi mengklaim otoritas atau kedekatan. (b) Aturan pribadi: (1) Tidak akan pernah memberi kode OTP/kata sandi ke siapa pun lewat pesan/telepon, apa pun alasannya. (2) Tidak akan pernah transfer uang berdasarkan permintaan mendadak tanpa verifikasi lewat kanal lain yang sudah kukenal sebelumnya. (3) Tidak akan pernah memasukkan data kartu/pembayaran di situs yang bukan resmi & tepercaya. (c) Langkah saat menemui percobaan penipuan: jangan klik/balas dulu → kenali tanda bahayanya → verifikasi lewat sumber/kanal terpisah → jangan bertindak sampai yakin → simpan bukti, blokir, & laporkan lewat fitur resmi. (d) Langkah pemulihan bila terlanjur tertipu: segera ganti kata sandi akun terkait dari perangkat aman, hubungi bank bila menyangkut uang/kartu, laporkan ke platform & bila perlu pihak berwajib, beri tahu orang dewasa tepercaya, & jangan menyalahkan diri berlebihan, cukup fokus pada langkah pemulihan. (e) Melindungi orang lain: sesekali berbagi contoh penipuan terbaru yang kudengar dengan keluarga & teman secara santai (bukan menggurui), menyepakati dengan keluarga 'kalau ada permintaan uang/data mendesak, selalu telepon dulu untuk memastikan', & langsung memberi tahu dengan tenang (tanpa menghakimi) kalau melihat seseorang hampir jadi korban.",explain:"Jawaban baik: 5 tanda bahaya yang mencakup berbagai pola (urgensi, permintaan sensitif, janji berlebihan, arah pembayaran terbalik, identitas tak terverifikasi), 3 aturan pribadi yang tegas & spesifik (bukan umum), langkah respons & pemulihan yang berurutan & benar, & rencana melindungi orang lain yang konkret & menghormati (mengajarkan cara berpikir, bukan sekadar melarang).",hint:"Bagian (b) harus benar-benar berupa larangan tegas ('tidak akan PERNAH...') untuk 3 hal paling berisiko: OTP/sandi, transfer tanpa verifikasi, & data kartu di situs tak resmi."},
];
